function kleinBottle(u, v, r = 1) {
  const halfU = u / 2;
  const cosU = Math.cos(u), sinU = Math.sin(u);
  const cosV = Math.cos(v), sinV = Math.sin(v);
  const x = r * (cosU * (1 + sinU) + sinV * (1 - cosU / 2));
  const y = r * sinU + cosV * (1 - cosU / 2);
  const z = r * Math.sin(halfU) * sinV;
  return [x, y, z];
}

